INSERT INTO `behavior_rules` VALUES ('0109f549-3fc9-4f87-8ece-1c823bf96dfb','เข้าร่วมกิจกรรมพิเศษ','เพิ่มคะแนน',5,'กิจกรรม',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('07105377-052f-43c3-9a84-a79ec4f6fd5c','หลีกเลี่ยงการปฏิบัติกิจกรรมหน้าเสาธงในตอนเช้า','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('09450b1e-8dfc-4de8-b120-6257e2ef13f7','การนำข้อมูลข่าวสารอันเป็นเท็จเข้าสู่ระบบคอมพิวเตอร์สื่อออนไลน์','ตัดคะแนน',-20,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('1d38ae42-1b20-4814-a897-0be89a741788','ทำร้ายร่างกายเพื่อนนักเรียนได้รับบาดเจ็บมีบาดแผลเล็กน้อย','ตัดคะแนน',-30,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('249f00de-4fbd-40a6-83de-39094871035a','ก่อเหตุทะเลาะวิวาททั่วไป','ตัดคะแนน',-20,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('28dd8f26-176b-4c72-b77b-0567d5863bcf','เสพสารเสพติด เช่น บุหรี่ กัญชา ยาบ้า หรืออุปกรณ์ในการเสพ มีไว้ในครอบครองหรือจำหน่าย','ตัดคะแนน',-50,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('2bb082f8-db92-4853-be4a-44a03003753e','จำหน่าย จ่ายแจก เอกสาร สื่ออิเล็กทรอนิกส์ และสิ่งของที่ใช้ในการบริโภค โดยมิได้ขออนุญาต','ตัดคะแนน',-30,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('2e325fb6-ec64-4bfa-b4ab-c6262287ddab','ปลอมแปลงเอกสาร แอบอ้างกิจกรรมของโรงเรียนต่อผู้ปกครองอันเป็นเท็จ','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('39b69054-5446-44aa-b76d-66afb19d3895','ความประพฤติดีเด่นประจำเดือน','เพิ่มคะแนน',10,'ความประพฤติ',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('3beac7b2-cf00-436e-894a-10c27a48a533','ลักขโมยและมีส่วนร่วมในการลักขโมยของผู้อื่นมาเป็นตนโดยเจตนา','ตัดคะแนน',-30,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('3c730205-ae2a-4bef-89d1-2e8de86a734a','แสดงตนเป็นนักเลง อันธพาล ก่อกวนความสงบสุขภายในห้องเรียน ปลุกปั่นยุยงให้เกิดการแตกแยก','ตัดคะแนน',-50,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('3eb4c7a1-36d1-4972-bb76-74a06be3c2b3','ไม่ทิ้งขยะลงในภาชนะที่รองรับ ทำให้สถานที่สกปรก','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('3fb302b1-f8cd-442f-b976-5da03919d79c','ใช้เครื่องประดับตกแต่งร่างกาย ใบหน้าอย่างไม่เหมาะสม','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('417e11c4-87ee-4394-ac68-1930c99e2097','แอบอ้างชื่อของผู้อื่นมาใช้แทนตน','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('428f5a3b-72ab-453b-b454-22d631b01e47','มาโรงเรียนสายหลัง 08.00 น. โดยไม่มีเหตุอันสมควร','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('50f03807-a4bd-4c03-84d3-920d60e1fbf2','ช่วยเหลืองานโรงเรียน','เพิ่มคะแนน',5,'ความดี',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('54e99574-12e2-437f-9ffc-feb61d466254','ไม่มีบันทึกพฤติกรรมเชิงลบทั้งภาคเรียน','เพิ่มคะแนน',10,'ความประพฤติ',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('58585a33-b678-4b92-925a-39052441c52d','เล่นประทัดหรือดอกไม้ไฟภายในโรงเรียน','ตัดคะแนน',-50,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('58a26a8e-baff-4a2c-810a-8304f0af2909','นำหนังสือ สื่อสิ่งพิมพ์ลามกอนาจาร เข้ามาเผยแพร่ในโรงเรียน','ตัดคะแนน',-20,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('58eee624-60a3-4c7f-8d9e-05f1d9de1dc4','ประพฤติผิดในทางชู้สาว ละเมิดทางเพศ ก่อนวัยอันควร','ตัดคะแนน',-50,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('66d2ad5b-b450-496d-91aa-343cdc63338e','นักเรียนหญิงซอยผม','ตัดคะแนน',-30,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('715a5716-d851-463c-be0a-d2e0db38deeb','เข้าและออกริมรั้วโรงเรียน โดยไม่ได้อนุญาต (ปีนรั้ว, ลอดรั้ว)','ตัดคะแนน',-20,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('76d95272-08d4-4acc-afeb-0e0a9ab484b6','ซื้อเครื่องดื่ม ขนม อาหารว่างริมรั้วโรงเรียน','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('869bce35-acab-452e-8946-edb728b162f1','ไม่สำรวมกิริยามารยาท นอกบริเวณโรงเรียนขณะอยู่ในเครื่องแบบนักเรียน','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('8f962e7e-b81d-4d3f-8fd6-5c703a735594','นำอาหาร ขนม หรือเครื่องดื่มทุกชนิดขึ้นไปทานบนอาคารเรียน','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('9fd14a49-c6e6-4a02-9c5a-1763c749bf72','กล่าวเท็จ ช่วยเหลือ ปกปิด ผู้กระทำความผิดอันเกิดความเสียหายต่อผู้อื่นและส่วนรวม','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('a745a226-24fe-4805-85d7-ffd23c22d776','มีพฤติกรรมลามกอนาจารนักเรียนด้วยกัน','ตัดคะแนน',-20,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('aa97c3f8-5d9f-4c5d-ae03-0db860a4a09a','หลีกเลี่ยงหรือไม่ทำความเคารพครู','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('b7ced745-9c50-479a-8753-427f9743e023','ใช้โทรศัพท์ เครื่องมือสื่อสารในโรงเรียนผิดวัตถุประสงค์และไม่เหมาะสมกับกาลเทศะ','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('c5876977-f349-42b3-9f88-38f6f2fb25b4','ชนะการแข่งขัน/ตัวแทนโรงเรียน','เพิ่มคะแนน',10,'กิจกรรม',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('c593aa9a-067e-465d-a355-41e03e920e63','เอาชายเสื้อออกนอกกางเกง กระโปรง (เครื่องแบบนักเรียนไทยพุทธ)','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('c8d17e8a-a399-4295-88a3-fb99823bac2a','ความผิดไม่ร้ายแรงอื่น ๆ (ตามดุลพินิจหัวหน้าระดับชั้น/หัวหน้าฝ่าย)','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('d62e9358-73f8-442b-8a2c-08c81ea7a866','หยอกล้อ เล่นกันรุนแรง จนเกิดบาดแผลหรือบาดเจ็บ','ตัดคะแนน',-10,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('e66dcfa4-8fba-401c-8089-444bd6ab6a09','ขีดเขียน ฝาผนัง โต๊ะ เก้าอี้ ในห้องส้วม ห้องเรียน และอาคารประกอบอื่น ๆ','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('e78acf53-bdf1-4413-9a8b-99ee173e9648','ช่วยเหลือเพื่อน/ผู้อื่น','เพิ่มคะแนน',5,'ความดี',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('ec1d7d70-48e6-4bd8-911c-0a9f72ca8cf1','มาสายหลังจากเข้าคาบเรียนที่ 1 โดยไม่มีเหตุอันควร','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('f2757afd-6e04-46f2-92fb-fb74abe01445','แต่งกายผิดระเบียบ','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('fa227d55-1b8e-483e-a1e5-9f8e63255d2c','ทำลายทรัพย์สินของผู้อื่นและของโรงเรียน','ตัดคะแนน',-20,'ความผิดร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43'),('fcb88370-a717-4fe4-8243-9b6900771d6d','หนีไม่เข้าชั้นเรียน','ตัดคะแนน',-5,'ความผิดไม่ร้ายแรง',NULL,'2026-07-05 08:48:43','2026-07-05 08:48:43');
