INSERT INTO `informant_reports` VALUES ('454391aa-8ead-457c-b6a5-7af7d64b220a','พฤติกรรมสูบบุหรี่หลังโรงเรียน','สิ่งเสพติดและอบายมุข','พบนักเรียนกลุ่มหนึ่งสูบบุหรี่บริเวณหลังโรงเรียน ช่วงพักกลางวัน ประมาณ 3–4 คน',1,NULL,NULL,'10004',NULL,'กำลังตรวจสอบ',NULL,'2026-07-05 15:48:44','2026-07-02 08:48:44','2026-07-02 08:48:44'),('99425ddd-d59f-4687-a65a-5a92389cc569','นักเรียนลักลอบออกนอกโรงเรียน','หนีเรียน','นักเรียนชั้น ม.2 กลุ่มหนึ่งมักออกนอกโรงเรียนในช่วงพัก โดยไม่ได้รับอนุญาต',0,'นายซูไฮมี มะเซ็ง','8408a9cb-681e-4590-abce-a60b0c813a3c','10005',NULL,'ดำเนินการแล้ว',NULL,'2026-07-05 15:48:44','2026-06-20 08:48:44','2026-06-20 08:48:44'),('99ab035b-5120-4b51-89d3-60691dceadc3','เหตุลักขโมยทรัพย์สินในห้องเรียน ม.1/1','อื่นๆ','มีการลักขโมยของในห้องเรียน ม.1/1 หลายครั้งในสัปดาห์นี้',0,'ด.ช. เก่ง เรียนดี','stud-uuid-1','10001',NULL,'กำลังตรวจสอบ',NULL,'2026-07-05 15:48:44','2026-07-01 08:48:44','2026-07-01 08:48:44'),('cab58262-ce5a-4fda-94cc-0aa135f5c5ca','พกพาสิ่งของมีคมเข้าโรงเรียน','อื่นๆ','นักเรียนนำสิ่งของมีคมเข้าโรงเรียน พบในกระเป๋านักเรียนชั้น ม.3',1,NULL,NULL,'10006',NULL,'รอดำเนินการ',NULL,'2026-07-05 15:48:44','2026-07-03 08:48:44','2026-07-03 08:48:44'),('ce0db17e-ef0d-46f1-85af-08dfca1fc7ab','ทุจริตนำโทรศัพท์เข้าห้องสอบ','อื่นๆ','มีนักเรียนนำโทรศัพท์เข้าห้องสอบ สังเกตเห็นในช่วงสอบกลางภาค',0,'ด.ช. เก่ง เรียนดี','stud-uuid-1','10002',NULL,'รอดำเนินการ',NULL,'2026-07-05 15:48:44','2026-07-04 08:48:44','2026-07-04 08:48:44'),('f12fedc3-bf0b-4577-9dc7-387aceda76c5','เหตุทะเลาะวิวาทบริเวณโรงอาหาร','ทะเลาะวิวาท','พบการทะเลาะวิวาทระหว่างนักเรียนต่างห้อง บริเวณโรงอาหาร',1,NULL,NULL,'10003',NULL,'กำลังตรวจสอบ',NULL,'2026-07-05 15:48:44','2026-06-30 08:48:44','2026-06-30 08:48:44');
